function fromSimpleIcon(icon: SimpleIcon, color: 'brand' | 'monochrome' = 'brand'): ChannelIcon {
  return {
    title: icon.title,
    path: icon.path,
    ...(color === 'brand' ? { hex: icon.hex } : {}),
    source: icon.source
  };
}

